async function handle401(){if(!window._sessionExpiring)try{await refreshUserSession(),showToast("Sessione rinnovata. Riprova l'operazione.",!1)}catch(e){showToast("Sessione scaduta. Effettua di nuovo il login.",!0),clearSession(),closeSheet(!0),showSection("splash-section"),showAuthForm()}}async function loadCards(){await ensureValidSession();const e=await fetch(SUPABASE_URL+"/rest/v1/cards?select=*&order=updated_at.desc",{headers:getAuthHeaders()});if(401===e.status)return handle401(),[];if(!e.ok)throw new Error("GET /cards "+e.status);return e.json()}async function addCard(e){await ensureValidSession();const t=await fetch(SUPABASE_URL+"/rest/v1/cards",{method:"POST",headers:{...getAuthHeaders(),Prefer:"return=representation"},body:JSON.stringify({...e,updated_at:(new Date).toISOString()})});if(401===t.status)return handle401(),null;if(!t.ok){const e=await t.text();throw new Error("POST /cards "+t.status+": "+e.slice(0,200))}return(await t.json())[0]}async function updateCard(e,t){await ensureValidSession();const s=await fetch(SUPABASE_URL+"/rest/v1/cards?id=eq."+e,{method:"PATCH",headers:{...getAuthHeaders(),Prefer:"return=representation"},body:JSON.stringify({...t,updated_at:(new Date).toISOString()})});if(401===s.status)return handle401(),null;if(!s.ok){const e=await s.text();throw new Error("PATCH /cards "+s.status+": "+e.slice(0,200))}return(await s.json())[0]}async function deleteCard(e){await ensureValidSession();const t=await fetch(SUPABASE_URL+"/rest/v1/cards?id=eq."+e,{method:"DELETE",headers:getAuthHeaders()});if(401!==t.status){if(!t.ok){const e=await t.text();throw new Error("DELETE /cards "+t.status+": "+e.slice(0,200))}}else handle401()}